import{_ as a,o as t,c as n,a5 as o}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"FR 3.5.6 - Approve and Deploy Media Campaign","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/3-5-6-approve-media-campaign/spec.md","filePath":"feature/media-package-campaign/3-5-6-approve-media-campaign/spec.md"}'),i={name:"feature/media-package-campaign/3-5-6-approve-media-campaign/spec.md"};function r(s,e,d,c,l,p){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="fr-3-5-6-approve-and-deploy-media-campaign" tabindex="-1">FR 3.5.6 - Approve and Deploy Media Campaign <a class="header-anchor" href="#fr-3-5-6-approve-and-deploy-media-campaign" aria-label="Permalink to &quot;FR 3.5.6 - Approve and Deploy Media Campaign&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Status</td><td>Implemented in code; Atlas migration verification and live flow testing pending (2026-10-10)</td></tr><tr><td>Roles</td><td>Client; Owner/Manager</td></tr><tr><td>Delivery task</td><td>DA-E50-07 / DA-948</td></tr></tbody></table><h2 id="outcome" tabindex="-1">Outcome <a class="header-anchor" href="#outcome" aria-label="Permalink to &quot;Outcome&quot;">​</a></h2><p>Both parties approve a campaign, then deployment creates one generic Mongo task per planned campaign work item in <code>backlog</code> and sets the campaign to <code>IN_PROGRESS</code>.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Approval needs Agency and Client timestamps for the same campaign content version; any edit invalidates both prior approvals.</li><li>Deploy rejects a campaign that is not fully approved.</li><li>Generated tasks contain <code>workspaceId</code>, <code>campaignId</code>, type, name, due date, and <code>status=backlog</code>; they initially have no assignee.</li><li>Retrying/deploying twice cannot duplicate a task for one campaign work item.</li><li>Client gives feedback; Manager edits, and both parties approve the revised version.</li><li>Confirmed 2026-10-14: Manager completes only after every linked Task is COMPLETED/CANCELLED and no Request is IN_PROGRESS. No reason bypass. Bulk cancellation is a separate explicit action with per-Task audit and one shared reason; preserve approval/content history. See ../campaign-closure/spec.md.</li></ul><h2 id="constraint" tabindex="-1">Constraint <a class="header-anchor" href="#constraint" aria-label="Permalink to &quot;Constraint&quot;">​</a></h2><p>PostgreSQL and MongoDB have no shared transaction. Deploy needs stable work-item ID plus Mongo unique/upsert key on <code>{campaignId, campaignWorkItemId}</code>, not only a <code>deployed_at</code> timestamp.</p><h2 id="delivery-gate-2026-10-08" tabindex="-1">Delivery gate (2026-10-08) <a class="header-anchor" href="#delivery-gate-2026-10-08" aria-label="Permalink to &quot;Delivery gate (2026-10-08)&quot;">​</a></h2><p>Mongo V2 is confirmed as the Task source of truth. Current PostgreSQL Task and Content Writing foreign keys still require integration work before deployment; do not create unrelated Task copies in both stores. One Workspace has one Campaign; new campaigns use new Workspaces, with an Owner duplication feature planned. See <a href="./../campaign-delivery-plan.html">delivery plan</a> for the remaining decisions.</p><h2 id="stage-3-review-and-approval-contract-2026-10-09" tabindex="-1">Stage 3 review and approval contract (2026-10-09) <a class="header-anchor" href="#stage-3-review-and-approval-contract-2026-10-09" aria-label="Permalink to &quot;Stage 3 review and approval contract (2026-10-09)&quot;">​</a></h2><ul><li>Client submits feedback for the Campaign version currently displayed. Feedback is append-only and does not change the plan or its content version.</li><li>Manager edits a draft plan; a material edit increments <code>contentVersion</code>, records a full immutable snapshot, and invalidates both previous approvals. No-op saves do not.</li><li>Each side approves the exact version it viewed. The same actor cannot supply both approvals. One-sided approval leaves status <code>DRAFT</code>; both sides approving the same version moves it to <code>APPROVED</code>. Approved content is immutable.</li><li>Approval requires a strategy, both timeline dates, and at least one work item. Feedback, edits, and approvals notify the opposite side through the existing inbox.</li><li>Campaign version snapshots and review events are retained for comparison/audit. The Workspace-scoped API enforces current Workspace membership and role.</li><li>Deploy and completion belong to Stage 4 and are not enabled by this stage.</li></ul><h2 id="stage-4-deployment-and-completion-contract" tabindex="-1">Stage 4 deployment and completion contract <a class="header-anchor" href="#stage-4-deployment-and-completion-contract" aria-label="Permalink to &quot;Stage 4 deployment and completion contract&quot;">​</a></h2><ul><li>Manager explicitly deploys a fully approved Campaign. Every planned work item becomes one generic Mongo <code>tasks</code> document in <code>BACKLOG</code>, retaining its stable <code>campaignWorkItemId</code>, Workspace, Campaign, type, name and due date. The new Task has no assignee or QC assignee. Retry must not alter an existing Task.</li><li>Deployment progress is durable in PostgreSQL. The Campaign becomes <code>IN_PROGRESS</code> only after Mongo confirms every work item. A failed or interrupted deployment can be retried using the same Task identities.</li><li>PostgreSQL editor content remains stored in its Yjs tables, referenced by Task UUID. Mongo is the Task source of truth; no second PostgreSQL Task is created.</li><li>Manager explicitly marks an IN_PROGRESS Campaign complete after all planned and supplemental Request Tasks reach COMPLETED/CANCELLED and all received Requests are processed. Preview shows blockers and PENDING cancellation count. Final completion rechecks server state; preserve actor/time/Task summary and durable PENDING cleanup. See ../campaign-closure/spec.md (2026-10-14 confirmation).</li><li>Existing Task IDs and editor content must be preserved during cutover. Local preflight on 2026-10-09 found zero PostgreSQL tasks/operations/snapshots; other environments must pass an independent preflight/backfill before switching.</li></ul>',14)])])}const h=a(i,[["render",r]]);export{g as __pageData,h as default};
